INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `image_url`, `display_order`, `is_active`) VALUES
(9, 'COMBUSTIBLE GLOW', 'combustible-glow', 'Combustibles oficiales con nitrometano y paquete de lubricación sintética y ricino para motores 2-tiempos y 4-tiempos.', '', 1, 1),
(10, 'TANQUES DE COMBUSTIBLE Y ACCESORIOS', 'tanques-de-combustible-y-accesorios', 'Tanques presurizados Dubro y Sullivan, mangueras de silicona glow, tapones herméticos y bombas manuales de combustible.', '', 2, 1),
(11, 'SERVOS Y ACCESORIOS', 'servos-y-accesorios', 'Servos estándar, micro servos metálicos de precisión Corona y Hextronix, engranajes y accesorios de timonería.', '', 3, 1),
(12, 'HELICES MOTORES GLOW', 'helices-motores-glow', 'Hélices de precisión Master Airscrew y APC para motores Glow de 2 y 4 tiempos, modelos bipala, tripala, propulsores pusher y balanceadores.', '', 4, 1),
(13, 'HELICES MOTORES ELECTRICOS', 'helices-motores-electricos', 'Hélices optimizadas para motores brushless y propulsión eléctrica, bajo peso, alta eficiencia y palas plegables.', '', 5, 1),
(14, 'HELICES DE MADERA', 'helices-de-madera', 'Hélices clásicas de madera de haya laminada y balsa densa de marcas Zinger, Master Airscrew y Turnigy para escala y gran empuje.', '', 6, 1),
(15, 'SPINNERS', 'spinners', 'Conos y spinners aerodinámicos de precisión Dubro, Sig y de aluminio/nylon en diámetros de 1.5 a 3 pulgadas, tuercas de seguridad y versiones tripala.', '', 7, 1),
(16, 'CONSTRUCCION', 'construccion', 'Accesorios y herrajes para armado y montaje estructural: bisagras de tela y cilíndricas, cuernos de mando, clevises metálicos/plásticos y varillas de empuje con rosca.', '', 8, 1),
(17, 'RUEDAS', 'ruedas', 'Ruedas de goma, espuma dura, ruedas ultralivianas de bajo impacto con huella Dubro y ruedas de cola (tailwheels) Sullivan de alta resistencia.', '', 9, 1),
(18, 'MONOKOTE', 'monokote', 'Films de recubrimiento termocontraíble Top Flite MonoKote original en acabados opacos, mate, metálico chrome y transparentes de alta adhesión.', '', 10, 1),
(19, 'OTROS PRODUCTOS', 'otros-productos', 'Accesorios eléctricos, conectores, receptores de radiofrecuencia, baterías, trenes de aterrizaje y componentes diversos de aeromodelismo.', '', 11, 1);
