(4, 'PM2018', 'Power Master 20% Nitro - 18% aceite', 'power-master-20-nitro-18-aceite', 9, 'RC Glow Competición', 'Mezcla de Competición EDM', '20% Nitro | 18% Aceite Puro EDM | Alto Rendimiento', 'Aviones Pylon Racing, Patrones F3A y Helicópteros 3D Nitro', 784.21, 65.30, NULL, 5, 'Competición', '/placeholder.webp', 0, 0, 'Power Master', 'Combustible de grado de competición con 20% nitro y paquete lubricante EDM 18% para máxima entrega de caballos de fuerza.'),
(5, 'DUBQ0206', '6 oz Tanque de Combustible Dubro # 406', '6-oz-tanque-de-combustible-dubro-406', 10, 'RC Glow .15 - .30', 'Polietileno Translúcido de Alta Densidad', '6 oz (180cc) | Sistema Hermético Antivibración | Dubro #406', 'Aviones Entrenadores .15 a .30 Glow y Park Flyers Nitro', 170.53, 14.20, NULL, 3, NULL, '/placeholder.webp', 0, 0, 'Dubro', 'Tanque original Dubro #406 con diseño antichoque, tapón de neopreno y tubos de latón para alimentación y presurización hermética.'),
