(157, 'AIB1563', 'Transmitter Soporte de baterias 8AA Flat', 'transmitter-soporte-de-baterias-8aa-flat-aib1563', 19, 'Accesorios para Transmisores RC', 'Plástico ABS de Alto Impacto con Resortes de Acero Inoxidable', 'Capacidad para 8 pilas AA (9.6V - 12V) | Configuración plana rectangular (Flat)', 'Emisoras tipo bandeja o compartimento plano de radio Futaba, FlySky y Spektrum', 102.08, 8.50, NULL, 3, 'Portapilas 8AA Flat', '/placeholder.webp', 0, 0, 'Futaba / Spektrum Compatible', 'Portabaterías plano para 8 pilas alcalinas o recargables AA con clip de conexión rápida para alimentación de radiocontroles.'),
(158, 'AIB16386', 'Pack de Transmisor AA 600mAH Ni-MH Battery Set (8pc)', 'pack-de-transmisor-aa-600mah-ni-mh-battery-set-8pc-aib16386', 19, 'Baterías y Alimentación RC', 'Celdas Recargables de Níquel-Metal Hidruro (Ni-MH)', 'Capacidad 600 mAh por celda | 1.2V por pila | Paquete de 8 unidades recargables', 'Transmisores de radiocontrol, receptores nitro y cajas de encendido', 37.23, 3.10, NULL, 1, 'Pack 8 Ni-MH', '/placeholder.webp', 0, 0, 'Turnigy', 'Set de 8 baterías recargables Ni-MH de 600mAh libres de efecto memoria para alimentar radiocontroles y módulos de campo.'),
(159, 'AIB17119', 'Eje tren principal 4 x 57 mm (2)', 'eje-tren-principal-4-x-57-mm-2-aib17119', 19, 'RC .40 - .90', 'Acero Templado Mecanizado con Rosca y Tuercas Autoblocantes', 'Diámetro 4 mm | Largo total 57 mm | Par de 2 ejes con tuercas nyloc', 'Montaje de ruedas en patas de tren principal de duraluminio o fibra de vidrio', 36.03, 3.00, NULL, 5, 'Ejes 4x57mm (2)', '/placeholder.webp', 0, 0, 'Dubro / General RC', 'Par de ejes de acero de 4 mm de diámetro por 57 mm de longitud diseñados para montaje rígido de ruedas en trenes principales.'),
(160, 'AIB17204', 'Programador de ESC marca Hobby King', 'programador-de-esc-marca-hobby-king-aib17204', 19, 'Electrónica de Control RC', 'Carcasa Compacta con LEDs Indicadores y Botones de Selección', 'Tarjeta de programación rápida para reguladores ESC de la serie HobbyKing BlueSeries y SS', 'Variadores de velocidad HobbyKing Brushless ESC de 20A a 100A', 72.06, 6.00, NULL, 1, 'Tarjeta ESC', '/products/AIB17204.jpg', 0, 1, 'HobbyKing', 'Tarjeta de programación portátil para ajustar freno motor, timing, corte de voltaje por celda LiPo y tipo de aceleración sin emitir beeps con el transmisor.'),
(161, 'AIB17496', 'Ignitor Remoto para Ignitor de Bujia', 'ignitor-remoto-para-ignitor-de-bujia-aib17496', 19, 'Motores Glow Nitro', 'Cable Aislado con Conector Lock-On de Bujía y Conector Externo de Fuselaje', 'Extensión para bujía glow plug con zócalo externo de conexión rápida', 'Aviones maqueta con motor carenado tipo cowl donde la bujía es inaccesible', 62.45, 5.20, NULL, 1, 'Ignitor Remoto', '/placeholder.webp', 0, 1, 'Sullivan / Dubro', 'Sistema remoto de encendido de bujía glow que permite conectar el calentador desde el exterior del fuselaje sin retirar la carena.'),
(162, 'AIB17672', 'Adaptador XT-60 a HXT (4mm)', 'adaptador-xt-60-a-hxt-4mm-aib17672', 19, 'Conectores Eléctricos RC', 'Carcasa de Nylon Inyectado con Pines Dorados Macizos', 'Adaptador directo sin cables: Conector XT60 a HXT 4.0 mm en una sola pieza', 'Baterías LiPo con conectores HXT o XT60 y cargadores o ESCs de distinto estándar', 31.22, 2.60, NULL, 2, 'Adaptador XT60-HXT', '/products/AIB17672.jpg', 0, 1, 'Turnigy', 'Adaptador compacto rígido sin cable para convertir conexiones XT-60 en conectores rojos HXT de 4mm con mínima resistencia interna.'),
(163, 'AIB18738', 'Multi terminal para Cargadores', 'multi-terminal-para-cargadores-aib18738', 19, 'Cargadores y Estaciones de Campo', 'Cables Siliconados 14AWG Multicolores con Pulpo de 8 Conectores', 'Bananas macho de 4 mm hacia XT60, T-Dean, JST, Futaba, EC3, Traxxas, Tamiya y Glow', 'Cargadores universales LiPo / NiMH / PB computarizados', 153.72, 12.80, NULL, 1, 'Multi-Cable 8 en 1', '/products/AIB18738.jpg', 0, 1, 'HobbyKing / Turnigy', 'Cable pulpo multi-conector 8 en 1 para cargar cualquier formato de batería o batería de receptor desde una sola salida de cargador.'),
