(167, 'AIB20015', 'Piloto civil para modelos 0,60 - 0,90', 'piloto-civil-para-modelos-0-60-0-90-aib20015', 19, 'Escala 1/6 a 1/5 (.60 - .90)', 'Vinilo Ligero Pintable / Plástico Termoformado', 'Busto de piloto civil con gafas y gorra de aviador | Altura aprox. 70 mm | Base plana', 'Maquetas de aviones civiles, Piper Cub, Cessna y aeronaves acrobáticas .60 a .90', 90.07, 7.50, NULL, 1, 'Piloto .60-.90', '/products/AIB20015.jpg', 0, 1, 'Williams Brothers / Great Planes', 'Figura de busto de piloto civil detallada para cabinas de aviones a escala clase .60 a .90, aportando realismo estético a la maqueta.'),
(168, 'AIB20031', 'Sistema de Patin de cola para modelos ,40 - ,60', 'sistema-de-patin-de-cola-para-modelos-40-60-aib20031', 19, 'RC .40 - .60', 'Alambre de Acero Templado + Soporte de Nylon y Resorte de Mando', 'Conjunto de patín de cola direccionable | Para modelos glow y eléctricos clase .40 a .60', 'Aviones glow y sport .40 a .60 con tren convencional (patín de cola)', 90.07, 7.50, NULL, 1, 'Patín de Cola .40-.60', '/products/AIB20031.jpg', 0, 1, 'Dubro / General RC', 'Sistema completo de patín de cola orientable conectado al timón de dirección para excelente maniobrabilidad en tierra y carreteo en pista.'),
(169, 'AIB24348', 'Cables de simulador para Turnigy GTX3', 'cables-de-simulador-para-turnigy-gtx3-aib24348', 19, 'Simuladores RC / USB', 'Cable USB Blindado con Conector Jack de Audio 3.5mm', 'Interfaz USB plug and play para PC | Compatible con transmisores Turnigy GTX3 y emisoras con salida PPM', 'Transmisores Turnigy GTX3, FlySky GT3B y software simulador VRC / Phoenix', 96.07, 8.00, NULL, 1, 'Cable Simulador', '/placeholder.webp', 0, 0, 'Turnigy', 'Cable adaptador USB para conectar emisoras Turnigy GTX3 al computador y practicar con simuladores de vuelo y radiocontrol.'),
